/* One draft for the whole owned roster; one journal operation on confirmation. */
(()=>{'use strict';
 const E=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const T=(en,ko)=>window.UKI18n?.language==='en'?en:ko;
 const L=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(T(en,ko))}</span>`;
 const A=()=>window.MMCampaignEconomy,units=g=>[...(g.fighters||[]),...(g.vehicles||[])];
 const names={work:['Work territory','영토 작업'],train:['Train','훈련'],develop:['Develop tactics','택틱 개발'],trade:['Trading Post','거래소 방문'],medical:['Medical escort','의료 호송'],bionics:['Fit bionics','바이오닉스']};
 const rewards={work:'+15 cr',train:'+2 XP',develop:'+1 '+T('tactic','택틱'),trade:'TP',medical:T('Treatment','치료 배정'),bionics:T('Treatment','시술 배정')};
 const roleNames={Leader:'리더',Champion:'챔피언',Ganger:'갱어',Prospect:'프로스펙트',Juve:'주브',Brute:'브루트','Hanger-on':'행어온',Pet:'펫',Beast:'비스트',Spyrer:'스파이어러'};
 const paths={work:'M4 20h16M6 16l9-9m-4-3 3-1 6 6-1 3-3-1-4-4z',train:'M4 18h16M7 14l4-4 3 2 4-6M14 6h4v4',develop:'M6 3h12v18H6zM9 8h6M9 12h6M9 16h3',trade:'M5 8h14l1 12H4L5 8zM8 8V6a4 4 0 0 1 8 0v2',medical:'M9 3h6v6h6v6h-6v6H9v-6H3V9h6z',bionics:'M14 5a5 5 0 0 0-6 6l-5 5a2 2 0 0 0 3 3l5-5a5 5 0 0 0 6-6l-3 3-3-3 3-3z',info:'M12 10v7M12 7v.1',check:'M5 12l4 4L19 6',clear:'M6 6l12 12M18 6 6 18',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75'};
 const icon=name=>`<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${name==='info'?'<circle cx="12" cy="12" r="9"/>':''}<path d="${paths[name]||paths.check}"/></svg>`;
 const label=action=>L(...names[action]);
 function shortState(f,base,completed){const states={'In Recovery':['In Recovery','회복 중'],'Critically Injured':['Critically Injured','치명적 부상'],'Critically Damaged':['Critically Damaged','치명적 손상'],Dead:['Dead','사망'],Retired:['Retired','은퇴'],Captured:['Captured','포로'],Enslaved:['Enslaved','노예'],Destroyed:['Destroyed','파괴']};const status=states[f.status]||(f.inRecovery?states['In Recovery']:null);if(status)return {en:status[0],ko:status[1]};if(completed.length)return {en:'Action already recorded',ko:'행동 기록 완료'};return base.reasons.length?{en:'Unavailable · see rules',ko:'행동 불가 · 규칙 확인'}:null;}

 function classification(f){const source=[f.fighterTypeId,f.catalogTypeId,f.presetId].map(id=>(window.RULES_DATA?.fighterTypes||[]).find(row=>row.source_verified&&row.id===id)).find(Boolean),roles=f.subtypes||f.fighter_subtypes||source?.fighter_subtypes||[];return (Array.isArray(roles)?roles:[]).map(role=>L(role,roleNames[role]||(window.RULES_DATA?.fighterSubtypes||[]).find(row=>[row.name,row.subtype_name].includes(role))?.name_ko||role)).join(' · ')||E(f.type||T('Model','모델'));}
 function open(c,g){
  if(!A()?.participants(c).some(row=>row===g))return;
  const roster=units(g),draft=new Map(),selected=new Set(),patientChoices=new Map();let notice='',busy=false,showRules=false;
  const key=(fid,slot='regular')=>fid+'\u0000'+slot,assignments=()=>[...draft.values()],notes=window.MMCampaignActionNotes;
  let root,modal,submit,foot;
  showModal(L('Assign cycle actions','사이클 행동 배정'),'<div class="ca-economy-dialog pcb-board" data-action-board></div>',T('Confirm assignments','배정 한 번에 확정'),()=>{
   if(busy)return false;
   if(!data.campaigns.includes(c)||!data.gangs.includes(g)){root.querySelector('[data-board-error]').textContent=T('Your roster changed. Reopen this board to use the current records.','기록이 바뀌었습니다. 창을 다시 열어 현재 명단에서 배정하세요.');submit.disabled=true;return false;}
   const plan=assignments(),preview=A().previewActions(c,g,plan);if(!plan.length||!preview.valid){draw();root.querySelector('[data-board-error]')?.focus();return false;}
   const operationKey=A().batchActionKey(c,g,plan);busy=true;root.setAttribute('aria-busy','true');for(const input of root.querySelectorAll('button,input,select'))input.disabled=true;
   return window.MMCampaignAutomation.apply(c,{key:operationKey,label:T('Batch Post-cycle actions','사이클 행동 일괄 처리'),gangIds:[g.id],errorTarget:root.querySelector('[data-board-error]'),mutate:state=>{const gang=state.gangs.find(row=>row.id===g.id);if(!gang)throw Error(T('Original roster unavailable.','원본 갱을 찾을 수 없습니다.'));return A().recordActions(state.campaign,gang,plan);}}).catch(error=>{if(root.isConnected){root.querySelector('[data-board-error]').textContent=error.message||String(error);return false;}throw error;}).finally(()=>{busy=false;if(root.isConnected){root.removeAttribute('aria-busy');draw(false,true);}});
  });
  root=document.querySelector('[data-action-board]');modal=root.closest('.modal');modal.id='campaign-cycle-actions-modal';modal.classList.add('pcb-modal');modal.closest('.modal-bg').classList.add('pcb-overlay');submit=modal.querySelector('#modal-submit');foot=document.createElement('div');foot.className='pcb-foot-summary';foot.setAttribute('data-board-footer','');modal.querySelector('.modal-foot').prepend(foot);
  function context(fid){const p=A().previewActions(c,g,assignments().filter(row=>row.fighterId!==fid));return {c:p.campaign,g:p.gang,f:units(p.gang).find(row=>row.id===fid)};}
  function eligible(ctx,action,slot='regular'){return A().actionEligibility(ctx.c,ctx.g,ctx.f,action,slot);}
  function injuries(f){return (f?.injuries||[]).filter(injury=>!injury.rule_data?.critical&&(window.RULES_DATA?.injuries||[]).some(source=>source.source_verified&&[injury.catalogId,injury.presetId].includes(source.id)&&!source.rule_data?.critical));}
  function focusId(node){if(!node||!root.contains(node))return null;for(const attr of ['boardAction','boardSelect','boardConnected','boardBulk','boardTarget','boardInjury','boardSelectAll','boardHelp'])if(Object.hasOwn(node.dataset,attr))return {attr,value:node.dataset[attr],fighter:node.dataset.boardFighter,slot:node.dataset.boardSlot};return null;}
  function restoreFocus(id){if(!id)return;const node=[...root.querySelectorAll('button,input,select')].find(node=>node.dataset[id.attr]===id.value&&node.dataset.boardFighter===id.fighter&&node.dataset.boardSlot===id.slot);if(node&&!node.disabled)node.focus({preventScroll:true});}
  function draw(keepFocus=true,keepError=false){
   const active=keepFocus?focusId(document.activeElement):null,scroll=modal.querySelector('.modal-body').scrollTop,opened=new Set([...root.querySelectorAll('[data-board-row-help][open]')].map(node=>node.dataset.boardRowHelp)),savedError=keepError?root.querySelector('[data-board-error]')?.textContent:'',preview=A().previewActions(c,g,assignments()),summary=preview.summary,contexts=new Map(roster.map(f=>[f.id,context(f.id)])),selectable=roster.filter(f=>{const ctx=contexts.get(f.id);return draft.has(key(f.id))||Object.keys(names).some(action=>eligible(ctx,action).allowed);}),chosen=[...selected].filter(id=>selectable.some(f=>f.id===id));
   for(const id of [...selected])if(!selectable.some(f=>f.id===id))selected.delete(id);
   const assigned=new Set(assignments().map(row=>row.fighterId)).size,metrics=[['Models assigned','배정 모델',`${assigned}<small> / ${roster.length}</small>`],['Credits now','즉시 크레딧',`+${summary.credits||0}<small> cr</small>`],['Total XP','XP 합계',`+${summary.xp||0}<small> XP</small>`],['Trade points','거래 포인트',`+${summary.tp||0}<small> TP</small>`]];
   root.innerHTML=`<div class="pcb-intro"><div class="pcb-gang-line"><strong data-user-text>${E(g.name)}</strong><span class="pcb-cycle">${L(`Cycle ${window.MMCampaignAutomation.cycle(c)}`,`${window.MMCampaignAutomation.cycle(c)}사이클`)}</span><button type="button" class="pcb-help-button" data-board-help aria-expanded="${showRules}">${icon('info')}${L('Rules','규칙 안내')}</button></div><p>${L('Assign actions across the roster, then confirm them together.','모델별 행동을 배정한 뒤 한 번에 확정하세요.')}</p><div class="pcb-metrics" data-board-summary aria-live="polite">${metrics.map(([en,ko,value])=>`<div><span>${L(en,ko)}</span><strong>${value}</strong></div>`).join('')}</div></div><div class="pcb-bulk"><div class="pcb-selection"><label class="pcb-select-all"><input type="checkbox" data-board-select-all ${chosen.length&&chosen.length===selectable.length?'checked':''} ${selectable.length?'':'disabled'}>${L('Select all available','행동 가능 모델 전체 선택')}</label><span>${L(`${chosen.length} selected`,`${chosen.length}명 선택`)}</span></div><div class="pcb-bulk-actions"><button type="button" data-board-bulk="train" ${chosen.length?'':'disabled'}>${icon('train')}${L('Train selected','선택 모델 훈련')}</button><button type="button" data-board-bulk="work" ${chosen.length?'':'disabled'}>${icon('work')}${L('Work selected','선택 모델 작업')}</button><button type="button" class="pcb-quiet" data-board-bulk="clear" ${chosen.length?'':'disabled'}>${L('Clear','배정 해제')}</button></div><p class="pcb-notice" data-board-notice role="status">${E(notice)}</p></div><div class="pcb-list">${roster.map((f,index)=>{
    const ctx=contexts.get(f.id),assignment=draft.get(key(f.id)),extra=draft.get(key(f.id,'connected')),errors=preview.errors.filter(error=>error.fighterId===f.id),choices=Object.keys(names).filter(action=>eligible(ctx,action).allowed||assignment?.action===action),canSelect=selectable.some(row=>row.id===f.id),base=A().baseEligibility(ctx.c,ctx.g,ctx.f),completed=A().actionHistory(c,g,f.id).filter(row=>row.slot!=='connected'),bonus=eligible(ctx,'trade','connected'),hasBonus=A().hasConnected(f)&&(bonus.allowed||extra),disabled=!choices.length&&!hasBonus;
    const actorReason=shortState(f,base,completed);
    let treatment='';
    if(assignment&&['medical','bionics'].includes(assignment.action)){
     const info=eligible(ctx,assignment.action),targetId=assignment.options?.targetId||'',target=(g.fighters||[]).find(row=>row.id===targetId),targets=info.targets||[],validInjuries=injuries(target),ids=assignment.options?.injuryIds||[];
     treatment=`<div class="pcb-treatment"><label>${L('Patient','치료 대상')}<select data-board-target="${E(f.id)}"><option value="">${E(T('Choose another fighter','다른 파이터 선택'))}</option>${targets.map(target=>`<option value="${E(target.id)}" ${target.id===targetId?'selected':''}>${E(target.name)}</option>`).join('')}${targetId&&!targets.some(target=>target.id===targetId)?`<option value="${E(targetId)}" selected disabled>${E(target?.name||targetId)} · ${E(T('Unavailable','선택 불가'))}</option>`:''}</select></label>${assignment.action==='bionics'&&target?`<fieldset><legend>${L('Lasting injuries · choose all to treat','시술할 지속 부상 · 복수 선택')}</legend>${validInjuries.map((injury,i)=>`<label class="pcb-injury"><input type="checkbox" data-board-injury="${E(injury.id)}" data-board-fighter="${E(f.id)}" ${ids.includes(injury.id)?'checked':''}><span data-user-text>${E(injury.name)}${validInjuries.filter(other=>other.name===injury.name).length>1?' · '+(i+1):''}</span><small>50 cr</small></label>`).join('')}</fieldset><p>${L(`${ids.length} injuries · ${Math.max(0,ids.length*50-info.discount)} credits after clinician discount`,`${ids.length}건 · 호송 모델 할인 적용 후 ${Math.max(0,ids.length*50-info.discount)}크레딧`)}</p>`:''}<p class="pcb-deferred">${L('Treatment and payment happen after income, at Update Roster.','치료와 비용 지불은 수입 후 명단 갱신에서 처리합니다.')}</p></div>`;
    }
    return `<article class="pcb-row ${disabled?'is-unavailable':''} ${assignment||extra?'is-assigned':''} ${errors.length?'has-error':''}" data-board-row="${E(f.id)}"><div class="pcb-identity"><label class="pcb-row-check"><input type="checkbox" data-board-select="${E(f.id)}" aria-label="${E(T('Select '+f.name,f.name+' 선택'))}" ${selected.has(f.id)?'checked':''} ${canSelect?'':'disabled'}></label><span class="pcb-number" aria-hidden="true">${String(index+1).padStart(2,'0')}</span><div><h3 data-user-text>${E(f.name)}</h3><p class="pcb-role">${classification(f)}</p>${disabled&&actorReason?`<span class="pcb-state">${L(actorReason.en,actorReason.ko)}</span>`:''}</div></div><div class="pcb-options" role="group" aria-label="${E(T(f.name+' actions',f.name+' 행동'))}">${choices.map(action=>{const info=eligible(ctx,action),current=assignment?.action===action;return `<button type="button" class="pcb-action ${current?'is-active':''}" data-board-action="${action}" data-board-fighter="${E(f.id)}" data-board-slot="regular" aria-pressed="${current}" ${!current&&!info.allowed?'disabled':''}>${icon(current?'check':action)}<span>${label(action)}</span><small>${action==='trade'?`+${info.tp} TP`:action==='develop'?L('+1 tactic','택틱 +1'):['medical','bionics'].includes(action)?L('Assign patient','대상 지정'):E(rewards[action])}</small></button>`;}).join('')}${!choices.length&&!actorReason?`<p class="pcb-state">${L('No regular action available','사용 가능한 일반 행동 없음')}</p>`:''}${hasBonus?`<button type="button" class="pcb-connected ${extra?'is-active':''}" data-board-connected="${E(f.id)}" aria-pressed="${!!extra}" ${!extra&&!bonus.allowed?'disabled':''}>${icon(extra?'check':'trade')}${L('Connected extra visit','커넥티드 추가 방문')}<small>+1 TP</small></button>`:''}</div>${treatment}${errors.length?`<p class="pcb-row-error" role="alert">${E(errors.map(error=>error.message).join(' · '))}</p>`:''}<details class="pcb-row-help" data-board-row-help="${E(f.id)}" ${opened.has(f.id)?'open':''}><summary aria-label="${E(T('Rules for '+f.name,f.name+' 행동 규칙'))}">${icon('info')}</summary><div>${assignment?notes.action(ctx.c,ctx.g,ctx.f,assignment.action):notes.model(ctx.c,ctx.g,ctx.f)}${base.reasons.length?`<p>${base.reasons.map(reason=>L(reason.en,reason.ko)).join(' · ')}</p>`:''}</div></details></article>`;
   }).join('')}</div><div class="pcb-reading" data-board-rules ${showRules?'':'hidden'}>${notes.intro()}${notes.guide(c,g).replace('<details class=','<details open class=')}</div><p class="pcb-error" role="alert" tabindex="-1" data-board-error>${E(savedError||(!preview.valid?(preview.errors.filter(error=>!error.fighterId).map(error=>error.message).join(' · ')||T('Review the highlighted assignments before confirming.','표시된 배정을 수정한 뒤 확정하세요.')):''))}</p>`;
   const all=root.querySelector('[data-board-select-all]');all.indeterminate=chosen.length>0&&chosen.length<selectable.length;
   foot.innerHTML=`<strong>${L(`${assigned} models · ${draft.size} actions`,`${assigned}명 · ${draft.size}개 행동`)}</strong><span>${summary.treatmentCost?L(`Treatment later: ${summary.treatmentCost} cr`,`추후 치료비 ${summary.treatmentCost} cr`):L(`Work territory ${summary.workUsed||0} / ${summary.workCap}`,`영토 작업 ${summary.workUsed||0} / ${summary.workCap}명`)}${summary.tactics?' · '+L(`${summary.tactics} new tactics`,`새 택틱 ${summary.tactics}개`):''}</span>`;
   submit.textContent=T(`Confirm ${assigned} models together`,`${assigned}명 한 번에 확정`);submit.disabled=busy||!draft.size||!preview.valid;
   window.UKI18n?.refresh(modal);restoreFocus(active);modal.querySelector('.modal-body').scrollTop=scroll;
  }
  function assign(fid,action,slot='regular'){
   const id=key(fid,slot),prior=draft.get(id);if(prior?.action===action){draft.delete(id);return;}
   const ctx=context(fid);if(!eligible(ctx,action,slot).allowed)return;
   draft.set(id,{fighterId:fid,action,slot,options:['medical','bionics'].includes(action)?{targetId:'',...(action==='bionics'?{injuryIds:[]}: {})}:{}});
  }
  root.addEventListener('click',event=>{
   if(busy)return;const button=event.target.closest('button');if(!button||!root.contains(button)||button.disabled)return;
   if(button.hasAttribute('data-board-help')){showRules=!showRules;draw();if(showRules)root.querySelector('[data-board-rules]').scrollIntoView({block:'start'});return;}
   if(button.dataset.boardAction){notice='';assign(button.dataset.boardFighter,button.dataset.boardAction);draw();return;}
   if(button.dataset.boardConnected){notice='';assign(button.dataset.boardConnected,'trade','connected');draw();return;}
   if(button.dataset.boardBulk){const action=button.dataset.boardBulk;let applied=0,skipped=0;for(const f of roster.filter(f=>selected.has(f.id))){if(action==='clear'){draft.delete(key(f.id));draft.delete(key(f.id,'connected'));selected.delete(f.id);applied++;continue;}const ctx=context(f.id);if(!eligible(ctx,action).allowed){skipped++;continue;}draft.set(key(f.id),{fighterId:f.id,action,slot:'regular',options:{}});selected.delete(f.id);applied++;}notice=skipped?T(`${applied} assigned. ${skipped} remain selected because of action limits; choose another action.`,`${applied}명 배정 · 제한으로 배정하지 못한 ${skipped}명은 선택 상태로 남겼습니다. 다른 행동을 지정하세요.`):T(`${applied} model assignments updated.`,`${applied}명의 배정을 변경했습니다.`);draw();}
  });
  root.addEventListener('change',event=>{
   if(busy)return;const input=event.target;
   if(input.hasAttribute('data-board-select-all')){selected.clear();if(input.checked)for(const checkbox of root.querySelectorAll('[data-board-select]:not(:disabled)'))selected.add(checkbox.dataset.boardSelect);draw();return;}
   if(input.dataset.boardSelect){input.checked?selected.add(input.dataset.boardSelect):selected.delete(input.dataset.boardSelect);draw();return;}
   if(input.dataset.boardTarget){const fid=input.dataset.boardTarget,entry=draft.get(key(fid));if(!entry)return;const old=entry.options.targetId;if(entry.action==='bionics')patientChoices.set(fid+'\u0000'+old,entry.options.injuryIds||[]);entry.options={targetId:input.value,...(entry.action==='bionics'?{injuryIds:patientChoices.get(fid+'\u0000'+input.value)||[]}: {})};draw();return;}
   if(input.dataset.boardInjury){const entry=draft.get(key(input.dataset.boardFighter));if(!entry)return;entry.options.injuryIds=[...input.closest('.pcb-treatment').querySelectorAll('[data-board-injury]:checked')].map(node=>node.dataset.boardInjury);draw();}
  });
  draw();
 }
 window.MMCampaignActionBoard={open};
})();
